/*
 * Auxiliary compile check for the CVE-2020-12826 candidate port.
 *
 * This does NOT build the kernel. It reproduces the exact macro definition and
 * the exact modified expressions/field types, so a syntax/type error in the
 * candidate lines would be caught. The kernel build itself is not runnable in
 * this environment (no make, no .config, no generated headers).
 */
typedef unsigned long long u64;
typedef unsigned int u32;

/* Copied verbatim from target include/linux/compiler.h:381 */
#define ACCESS_ONCE(x) (*(volatile typeof(x) *)&(x))

struct task_struct {
	u64 parent_exec_id;
	u64 self_exec_id;
};

/* CU-002: fs/exec.c setup_new_exec() */
void setup_new_exec(struct task_struct *current)
{
	ACCESS_ONCE(current->self_exec_id) = current->self_exec_id + 1;
}

/* CU-003: kernel/signal.c do_notify_parent() */
int do_notify_parent(struct task_struct *tsk)
{
	int sig = 10;

	if (sig != 17) {
		if (tsk->parent_exec_id != ACCESS_ONCE(tsk->parent->self_exec_id))
			sig = 17;
	}
	return sig;
}

/* CU-001: both fields must be 64-bit (8 bytes) */
typedef char assert_parent_exec_id_64[
	(sizeof(((struct task_struct *)0)->parent_exec_id) == 8) ? 1 : -1];
typedef char assert_self_exec_id_64[
	(sizeof(((struct task_struct *)0)->self_exec_id) == 8) ? 1 : -1];

